function Row({ label }) {
  const [checked, setChecked] = useState(false);
  return (
    <li>
      <input type="checkbox" checked={checked} onChange={e => setChecked(e.target.checked)} /> {label}
    </li>
  );
}

function App() {
  const [items, setItems] = useState([
    { id: 'a', label: 'Apple' },
    { id: 'b', label: 'Banana' },
  ]);
  const addToTop = () =>
    setItems(prev => [{ id: crypto.randomUUID(), label: 'New ' + prev.length }, ...prev]);
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <button onClick={addToTop}>Add to top</button>
      <ul>
        {items.map(item => (
          <Row key={item.id} label={item.label} />
        ))}
      </ul>
    </div>
  );
}

function Item({ label }) {
  const [note, setNote] = useState('');
  return (
    <li>
      {label}{' '}
      <input value={note} onChange={e => setNote(e.target.value)} placeholder="note" />
    </li>
  );
}

function App() {
  const [items, setItems] = useState([
    { id: 'a', label: 'First' },
    { id: 'b', label: 'Second' },
  ]);
  const addToFront = () =>
    setItems(prev => [{ id: crypto.randomUUID(), label: 'Item ' + (prev.length + 1) }, ...prev]);
  const remove = id => setItems(prev => prev.filter(i => i.id !== id));
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <button onClick={addToFront}>Add to front</button>
      <ul>
        {items.map(item => (
          <li key={item.id} style={{ listStyle: 'none' }}>
            <Item label={item.label} />{' '}
            <button onClick={() => remove(item.id)}>x</button>
          </li>
        ))}
      </ul>
    </div>
  );
}
